   354→impl<L, R, Tx> RecoveredTx<Tx> for Either<L, R>
   355→where
   356→    L: RecoveredTx<Tx>,
   357→    R: RecoveredTx<Tx>,
   358→{
   359→    fn tx(&self) -> &Tx {
   360→        match self {
   361→            Self::Left(l) => l.tx(),
   362→            Self::Right(r) => r.tx(),
   363→        }
   364→    }
   365→
   366→    fn signer(&self) -> &Address {
   367→        match self {
   368→            Self::Left(l) => l.signer(),
   369→            Self::Right(r) => r.signer(),
   370→        }
   371→    }
   372→}
